package com.example;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("dropit")
public interface DropItConfig extends Config
{
	@ConfigItem(
			keyName = "twitchChannel",
			name = "Twitch Channel",
			description = "The exact name of the Twitch channel to monitor (e.g., bionichusky)",
			position = 1
	)
	default String twitchChannel()
	{
		return "";
	}

	@ConfigItem(
			keyName = "allowedBotName",
			name = "Allowed Bot Name (Optional)",
			description = "If filled in, ONLY messages from this exact user/bot will trigger the penalty (e.g., nightbot). Leave blank to allow anyone.",
			position = 2
	)
	default String allowedBotName()
	{
		return "";
	}
}

package com.example;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class DropItOverlay extends Overlay
{
    private final Client client;
    private final DropItPlugin plugin;

    @Inject
    private DropItOverlay(Client client, DropItPlugin plugin)
    {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (plugin.isWarningActive())
        {
            renderWarning(graphics);
        }
        else if (plugin.isPenaltyActive())
        {
            renderPenalty(graphics);
        }
        return null;
    }

    private void renderWarning(Graphics2D graphics)
    {
        // 1. Draw the pulsing red screen
        long time = System.currentTimeMillis();
        int alpha = (int) (100 + 100 * Math.sin(time / 150.0)); // Math for the pulse effect
        graphics.setColor(new Color(255, 0, 0, Math.max(0, Math.min(255, alpha))));
        graphics.fill(new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight()));

        // 2. Draw the giant countdown timer in the middle of the screen
        String text = String.valueOf(plugin.getWarningTimer());
        graphics.setFont(new Font("Arial", Font.BOLD, 72));
        FontMetrics metrics = graphics.getFontMetrics();
        int x = (client.getCanvasWidth() - metrics.stringWidth(text)) / 2;
        int y = (client.getCanvasHeight() - metrics.getHeight()) / 2 + metrics.getAscent();

        // Add a black drop-shadow to the text so it's readable anywhere
        graphics.setColor(Color.BLACK);
        graphics.drawString(text, x + 4, y + 4);

        // Draw the white text
        graphics.setColor(Color.WHITE);
        graphics.drawString(text, x, y);
    }

    private void renderPenalty(Graphics2D graphics)
    {
        // Check if the player currently has a weapon equipped
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return;
        }

        Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());

        // If they have a weapon equipped during the penalty phase...
        if (weapon != null && weapon.getId() > 0)
        {
            Widget invWidget = client.getWidget(ComponentID.INVENTORY_CONTAINER);
            if (invWidget != null && !invWidget.isHidden())
            {
                // 1. Draw the blackout box over the inventory
                Rectangle bounds = invWidget.getBounds();
                graphics.setColor(Color.BLACK);
                graphics.fill(bounds);

                // 2. Draw the giant clown emoji
                String text = "🤡";
                graphics.setFont(new Font("Segoe UI Emoji", Font.PLAIN, 48));
                FontMetrics metrics = graphics.getFontMetrics();
                int x = bounds.x + (bounds.width - metrics.stringWidth(text)) / 2;
                int y = bounds.y + (bounds.height - metrics.getHeight()) / 2 + metrics.getAscent();

                graphics.setColor(Color.WHITE);
                graphics.drawString(text, x, y);
            }
        }
    }
}

package com.example;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

import java.time.Instant;

@Slf4j
@PluginDescriptor(
		name = "Drop It",
		description = "A Twitch chat integration plugin that enforces a drop your weapon penalty game.",
		tags = {"twitch", "integration", "penalty", "streamer"}
)
public class DropItPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread; // <--- Here is the magical thread manager!

	@Inject
	private DropItConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DropItOverlay overlay;

	@Inject
	private OkHttpClient okHttpClient;

	private WebSocket webSocket;

	// State Variables for the Overlay
	@Getter
	private boolean warningActive = false;
	@Getter
	private int warningTimer = 0;

	@Getter
	private boolean penaltyActive = false;
	@Getter
	private int penaltyTimer = 0;

	private Instant lastSecondUpdate = null;

	@Provides
	DropItConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DropItConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
		connectToTwitch();
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		disconnectFromTwitch();
		resetTimers();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Reconnect if the streamer changes the Twitch Channel in settings
		if (event.getGroup().equals("dropit") && event.getKey().equals("twitchChannel"))
		{
			connectToTwitch();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Manage the real-time seconds for the timers
		if (lastSecondUpdate != null && Instant.now().isAfter(lastSecondUpdate.plusSeconds(1)))
		{
			lastSecondUpdate = Instant.now();

			if (warningActive)
			{
				warningTimer--;
				if (warningTimer <= 0)
				{
					warningActive = false;
					penaltyActive = true;
					penaltyTimer = 60; // Start the 60 second penalty
				}
			}
			else if (penaltyActive)
			{
				penaltyTimer--;
				if (penaltyTimer <= 0)
				{
					resetTimers(); // Penalty is over!
				}
			}
		}
	}

	private void connectToTwitch()
	{
		disconnectFromTwitch();

		String channel = config.twitchChannel();
		if (channel == null || channel.isEmpty())
		{
			return;
		}

		String finalChannel = channel.toLowerCase();
		Request request = new Request.Builder()
				.url("wss://irc-ws.chat.twitch.tv:443")
				.build();

		webSocket = okHttpClient.newWebSocket(request, new WebSocketListener()
		{
			@Override
			public void onOpen(WebSocket webSocket, Response response)
			{
				// Connect as an anonymous JustinFan user
				webSocket.send("PASS SCHMOOPIIE");
				int randomNum = (int) (Math.random() * 99999) + 10000;
				webSocket.send("NICK justinfan" + randomNum);
				webSocket.send("JOIN #" + finalChannel);
				log.info("Drop It connected to Twitch channel: " + finalChannel);
			}

			@Override
			public void onMessage(WebSocket webSocket, String text)
			{
				// Twitch requires an automated ping/pong to keep the connection alive
				if (text.startsWith("PING"))
				{
					webSocket.send("PONG :tmi.twitch.tv");
					return;
				}

				// If a chat message comes through
				if (text.contains("PRIVMSG #" + finalChannel + " :"))
				{
					int exclamationIndex = text.indexOf("!");
					if (exclamationIndex != -1 && text.startsWith(":"))
					{
						String sender = text.substring(1, exclamationIndex);
						String message = text.substring(text.indexOf(":", text.indexOf("PRIVMSG")) + 1).trim();

						// Check for the trigger command
						if (message.equalsIgnoreCase("!dropit"))
						{
							handleDropItCommand(sender);
						}
					}
				}
			}
		});
	}

	private void disconnectFromTwitch()
	{
		if (webSocket != null)
		{
			webSocket.close(1000, "Plugin stopped or config changed");
			webSocket = null;
		}
	}

	private void handleDropItCommand(String sender)
	{
		String allowedBot = config.allowedBotName();
		// Check whitelist if the streamer configured one
		if (allowedBot != null && !allowedBot.isEmpty())
		{
			if (!sender.equalsIgnoreCase(allowedBot.trim()))
			{
				return;
			}
		}

		// Trigger the Warning State
		warningActive = true;
		warningTimer = 5;
		penaltyActive = false;
		penaltyTimer = 0;
		lastSecondUpdate = Instant.now();

		// Play the Armadyl Crossbow sound using RuneLite's actual ClientThread
		clientThread.invokeLater(() -> {
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.playSoundEffect(2277);
			}
		});
	}

	private void resetTimers()
	{
		warningActive = false;
		warningTimer = 0;
		penaltyActive = false;
		penaltyTimer = 0;
		lastSecondUpdate = null;
	}
}

package com.example;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ExamplePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DropItPlugin.class);
		RuneLite.main(args);
	}
}
